/// `worm init` command.
library;

import 'dart:io';

import '../worm_command_runner.dart';

/// The 18 prescribed `lib/src/` subdirectories. Alphabetically
/// sorted for deterministic output. Order and membership are
/// asserted by the init-command tests — do not edit without
/// updating those tests.
const List<String> _srcDirectories = <String>[
  'adapter',
  'cast',
  'cli',
  'config',
  'exception',
  'factory',
  'logging',
  'migration',
  'model',
  'naming',
  'observer',
  'predicate',
  'query',
  'registry',
  'relation',
  'schema',
  'seeder',
  'validation',
];

/// Project-root directories created alongside `lib/src/`.
const List<String> _rootDirectories = <String>[
  'migrations',
  'seeds',
  'lib/models',
  'lib/factories',
  'config',
];

const String _wormConfigTemplate = '''
// Generated by `worm init`. Edit to wire up your real adapter(s).
import 'package:worm/worm.dart';

/// Top-level worm configuration for this project.
const WormConfig wormConfig = WormConfig(
  defaultConnection: 'default',
  connections: <String, ConnectionConfig>{
    // 'default': ConnectionConfig(
    //   driver: 'postgres',
    //   host: 'localhost',
    //   database: 'myapp',
    // ),
  },
);
''';

/// Scaffolds the prescribed worm project layout.
///
/// Idempotent: existing directories and files are left untouched
/// and reported via `Already exists` lines on `context.out`.
final class InitCommand extends WormCommand {
  /// Creates an [InitCommand].
  InitCommand(super.context);

  @override
  String get name => 'init';

  @override
  String get description =>
      'Initialize worm in this Dart project. Scaffolds the 18 lib/src/ '
      'subdirectories, migrations/, seeds/, lib/models/, lib/factories/, '
      'config/, and writes a config/worm_config.dart template. '
      'Idempotent — re-running prints "Already exists" for anything that '
      'is already present.';

  @override
  Future<int> run() async {
    for (final dir in _srcDirectories) {
      _createDirectory('lib/src/$dir');
    }
    for (final dir in _rootDirectories) {
      _createDirectory(dir);
    }
    _createFileIfAbsent('config/worm_config.dart', _wormConfigTemplate);
    return 0;
  }

  void _createDirectory(String relative) {
    final dir = Directory('${context.projectRoot.path}/$relative');
    if (dir.existsSync()) {
      context.out.writeln('Already exists  $relative/');
      return;
    }
    dir.createSync(recursive: true);
    context.out.writeln('created         $relative/');
  }

  void _createFileIfAbsent(String relative, String content) {
    final file = File('${context.projectRoot.path}/$relative');
    if (file.existsSync()) {
      context.out.writeln('Already exists  $relative');
      return;
    }
    file
      ..createSync(recursive: true)
      ..writeAsStringSync(content);
    context.out.writeln('created         $relative');
  }
}
